mapper.select:
SELECT c.id, c.title, c.description, c.cover_image, c.link_url, c.teacher_id, c.teacher_name, c.category_id, cat.name AS category_name, c.price, c.duration, c.level, c.status, c.student_count, c.rating, c.tags, c.created_at FROM t_course c LEFT JOIN t_category cat ON c.category_id = cat.id AND cat.deleted = 0 WHERE c.deleted = 0 AND c.status = 1
AND (c.title LIKE CONCAT('%', #{query.keyword}, '%') OR c.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND c.category_id = #{query.categoryId}
AND c.level = #{query.level}
AND c.price >= #{query.minPrice}
AND c.price <= #{query.maxPrice}
ORDER BY
c.price c.student_count c.rating c.created_at
ASC DESC
